Tool response:
Tool: find_sites
Description: Find Sites
Parameters:
    {
      "type": "object",
      "properties": {
        "check_in_date": {
          "type": "string",
          "description": "Check-in date in YYYY-MM-DD format",
          "title": "Check In Date"
        },
        "check_out_date": {
          "type": "string",
          "description": "Check-out date in YYYY-MM-DD format",
          "title": "Check Out Date"
        },
        "adults": {
          "type": "integer",
          "minimum": 1,
          "description": "Number of adults",
          "title": "Adults"
        },
        "children": {
          "type": "integer",
          "minimum": 0,
          "description": "Number of children",
          "title": "Children"
        }
      },
      "required": [
        "check_in_date",
        "check_out_date",
        "adults",
        "children"
      ]
    }

